Definition open_copyins (ms : machine_state) : list (word * nat) := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S30!1+2!1,3|600;!2+10+P!2'^M#1}1$ms;R+A!3,^Y1!4,^[0+P2!3'eJ!1'^O#12'aU!1,N1").

Definition check_open_result_copyins (reads : list (word * nat))
    (eff : SyscallEffect) (m : Model) (mk : word -> Model) : check_result := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S10!1+2!1,3|600;$reads;R!1+0!2+10+P$eff;R+bZ$m;R+5$mk;R%~R0+5!3'eK#4#3!3'eC!1'eL#3#2#1").

Lemma effect_from_copyins_and_clear : forall eff reads core,
  eff_copyins eff = reads -> clear_copyins eff = core ->
  eff = with_copyins reads core.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S;0!1+2!1,3|600;!2+10+P!1+01!1+2!1,3|600;|30;!1+0!2+133|30;!1+0!2+100!1,N1!6,M#>#=#<#;#:8!6,M#;#:#9#8#7#5$eff;R+bZ-bZRN$s;R+bZ%reads;R2%core;R+bZ%~R!3+@2!1'eM#3#2%~R!3+@+bZ!1'eL#4#2!3+@+bZ#5!2'^K#4#3#11$eff_ret;R3$eff_writes;R!1+0!2+13!1+0!1+2!1,34$eff_zeros;R5$eff_unmaps;R5$eff_copies;R!1+0+O$eff_copyins;R!1+0!2+13+P!6$ret;R0$ws;R!1+0!2+10!1+0!1+2!1,36$zs;R7$us;R7$cs;R!1+0+O$copyins;R2$reads;R2$core;R+bZ$Hreads;R!3+@2!1'eM!6,M#8#7#6#5#4#3#2$Hcore;R!3+@+bZ!1'eL!6,M#9#8#7#6#5#4#2!7'=2#4$copyins;R2%Hcore;R!3+@+bZ!1'eL!6,M#;#:#9#8#7#1#4!3+@+bZ!6,M#<#;#:#9#8#2!2'^K#6#5$Hcore;R!3+@+bZ!1'eL!6,M#:#9#8#7#6#4#3vdvd&H;R-@RN$s;R+bZ$~R!3+@+bZ!6,M#<#;#:#9#88#1%~R!3+@+bZ#2#6!3+@+bZ!6,M#>#=#<#;#:#8!6,M!1'L#7!1'^2#7!1'^0#7!1'\#7!1'^1#7#8#11$H;R!3+@+bZ!6,M#;#:#9#8#78#4!1$H;R!3+@+bZ!6,M#<#;#:#9#88#5&H0;R#1!3+@+bZ!6,M#=#<#;#:#98#6!6'^A+bZ9$s;R+bZ!3+@+bZ!6,M#?#>#=#<#;#9!6,M!1'L#1!1'^2#1!1'^0#1!1'\#1!1'^1#1#9!2,6+bZ!6,M!1'L9!1'^29!1'^09!1'\9!1'^19#8#7#1#1!1$s;R+bZ%~R!3+@+bZ#1#5!3+@+bZ!6,M#=#<#;#:#9#7!6,M!1'L#6!1'^2#6!1'^0#6!1'\#6!1'^1#6#7#4!1#1!2,6+bZ#5!3+@+bZ:!6,M!1'L#4!1'^2#4!1'^0#4!1'\#4!1'^1#4#5!3+@+bZ:!2'^K#5#4#5#2#1#6#5#4#3#2#1").
Qed.

Lemma check_open_result_copyins_never_unmodeled : forall reads eff m mk,
  check_open_result_copyins reads eff m mk <> CheckUnmodeled.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1+2!1,3|600;!3+@+dP,eE,dR$reads;R!1+0!2+10+P$eff;R+bZ$m;R+5$mk;R%~R0+5vd&b;R!2'eN!1'eM#3#4+>->RN$b;R+>!1'^F!3+@+dP->RN$~R+>+dP#12!3'eC!1'eL#5#4#3,eE,dR#12!3'eO!1'eL#4#3#2vd$H;R1&H0;R!6'^A+dP,eE$e;R+dP-dPRN$c;R+dPw#13$m;R+5$evs;R!1+0+c1+^B+^D+^B,K,dR#1+^B!2'^E+^B#1!1'^F1!1'^F!3+@+dP!4'eP#4#3#2#1,dR").
Qed.

Lemma check_open_result_copyins_ok_iff :
  forall reads eff m (mk : word -> Model) m' evs,
  check_open_result_copyins reads eff m mk = CheckOk m' evs <->
  ((exists e, In e openat_errnos /\
      eff = with_copyins reads (mkEffect (errno_ret e) [] []) /\
      m' = m /\ evs = [])
   \/ (exists fd, fd_lookup (m_fds m) fd = None /\
      fd = alloc_fd (m_fds m) /\
